import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.EUByU7Iq.js";const p=JSON.parse('{"title":"第八章 高度危险责任","description":"","frontmatter":{"title":"第八章 高度危险责任","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/dibazhang：gaoduweixianzeren.md","filePath":"blogs/CC/第八章：高度危险责任.md"}'),i={name:"blogs/CC/dibazhang：gaoduweixianzeren.md"};function h(l,a,n,d,s,c){return t(),r("div",null,[...a[0]||(a[0]=[o('<h3 id="第一千二百三十六条" tabindex="-1">第一千二百三十六条 <a class="header-anchor" href="#第一千二百三十六条" aria-label="Permalink to &quot;第一千二百三十六条&quot;">​</a></h3><p>从事高度危险作业造成他人损害的，应当承担侵权责任。</p><h3 id="第一千二百三十七条" tabindex="-1">第一千二百三十七条 <a class="header-anchor" href="#第一千二百三十七条" aria-label="Permalink to &quot;第一千二百三十七条&quot;">​</a></h3><p>民用核设施或者运入运出核设施的核材料发生核事故造成他人损害的，民用核设施的营运单位应当承担侵权责任；但是，能够证明损害是因战争、武装冲突、暴乱等情形或者受害人故意造成的，不承担责任。</p><h3 id="第一千二百三十八条" tabindex="-1">第一千二百三十八条 <a class="header-anchor" href="#第一千二百三十八条" aria-label="Permalink to &quot;第一千二百三十八条&quot;">​</a></h3><p>民用航空器造成他人损害的，民用航空器的经营者应当承担侵权责任；但是，能够证明损害是因受害人故意造成的，不承担责任。</p><h3 id="第一千二百三十九条" tabindex="-1">第一千二百三十九条 <a class="header-anchor" href="#第一千二百三十九条" aria-label="Permalink to &quot;第一千二百三十九条&quot;">​</a></h3><p>占有或者使用易燃、易爆、剧毒、高放射性、强腐蚀性、高致病性等高度危险物造成他人损害的，占有人或者使用人应当承担侵权责任；但是，能够证明损害是因受害人故意或者不可抗力造成的，不承担责任。被侵权人对损害的发生有重大过失的，可以减轻占有人或者使用人的责任。</p><h3 id="第一千二百四十条" tabindex="-1">第一千二百四十条 <a class="header-anchor" href="#第一千二百四十条" aria-label="Permalink to &quot;第一千二百四十条&quot;">​</a></h3><p>从事高空、高压、地下挖掘活动或者使用高速轨道运输工具造成他人损害的，经营者应当承担侵权责任；但是，能够证明损害是因受害人故意或者不可抗力造成的，不承担责任。被侵权人对损害的发生有重大过失的，可以减轻经营者的责任。</p><h3 id="第一千二百四十一条" tabindex="-1">第一千二百四十一条 <a class="header-anchor" href="#第一千二百四十一条" aria-label="Permalink to &quot;第一千二百四十一条&quot;">​</a></h3><p>遗失、抛弃高度危险物造成他人损害的，由所有人承担侵权责任。所有人将高度危险物交由他人管理的，由管理人承担侵权责任；所有人有过错的，与管理人承担连带责任。</p><h3 id="第一千二百四十二条" tabindex="-1">第一千二百四十二条 <a class="header-anchor" href="#第一千二百四十二条" aria-label="Permalink to &quot;第一千二百四十二条&quot;">​</a></h3><p>非法占有高度危险物造成他人损害的，由非法占有人承担侵权责任。所有人、管理人不能证明对防止非法占有尽到高度注意义务的，与非法占有人承担连带责任。</p><h3 id="第一千二百四十三条" tabindex="-1">第一千二百四十三条 <a class="header-anchor" href="#第一千二百四十三条" aria-label="Permalink to &quot;第一千二百四十三条&quot;">​</a></h3><p>未经许可进入高度危险活动区域或者高度危险物存放区域受到损害，管理人能够证明已经采取足够安全措施并尽到充分警示义务的，可以减轻或者不承担责任。</p><h3 id="第一千二百四十四条" tabindex="-1">第一千二百四十四条 <a class="header-anchor" href="#第一千二百四十四条" aria-label="Permalink to &quot;第一千二百四十四条&quot;">​</a></h3><p>承担高度危险责任，法律规定赔偿限额的，依照其规定，但是行为人有故意或者重大过失的除外。</p>',18)])])}const u=e(i,[["render",h]]);export{p as __pageData,u as default};
